#!/usr/bin/env node
// Generates src/styles/tokens.generated.css: CSS custom properties for every brand × theme configuration.
// Layers emitted: brand, theme, typography styles, components (primitives core/map are never exposed). Do not edit the output.
import { writeFileSync, mkdirSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { loadSets, config, MODES } from "./lib/tokens.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = resolve(ROOT, "src/styles/tokens.generated.css");
const { BRANDS, sets } = loadSets(ROOT);

const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();
const varName = (name, extra) =>
  "--" + [...name.split("."), ...(extra ? [extra] : [])].map(kebab).join("-");
const PX = new Set([
  "sizing",
  "spacing",
  "borderRadius",
  "borderWidth",
  "fontSizes",
  "lineHeights",
  "dimension",
]);
// Inter is self-hosted through @fontsource-variable/inter (registers "Inter Variable").
const family = (f) =>
  f === "Inter"
    ? `"Inter Variable", "Inter", system-ui, sans-serif`
    : `"${f}", system-ui, sans-serif`;
const shadow = (s) =>
  [s.x, s.y, s.blur, s.spread].map((n) => (Number(n) === 0 ? "0" : `${n}px`)).join(" ") +
  ` ${s.color}`;

function css(type, v) {
  if (PX.has(type)) return Number(v) === 0 ? "0" : `${v}px`;
  if (type === "letterSpacing") return `${parseFloat(v) / 100}em`;
  if (type === "fontFamilies") return family(v);
  if (type === "boxShadow") return Array.isArray(v) ? v.map(shadow).join(", ") : shadow(v);
  return String(v);
}
// typography composite property → CSS property suffix and value type
const TY = {
  fontFamily: ["font-family", "fontFamilies"],
  fontWeight: ["font-weight", "fontWeights"],
  fontSize: ["font-size", "fontSizes"],
  lineHeight: ["line-height", "lineHeights"],
  letterSpacing: ["letter-spacing", "letterSpacing"],
  textCase: ["text-transform", "textCase"],
};
const textTransform = (v) => (v === "none" ? "none" : v);

function block(brand, mode) {
  const { res } = config(sets, brand, mode);
  const lines = [];
  const emit = (name, tk) => {
    if (tk.type === "boolean") return;
    const v = res(name);
    if (tk.type === "typography") {
      for (const [k, val] of Object.entries(v)) {
        const [prop, t] = TY[k] ?? [null];
        if (prop)
          lines.push(
            `  ${varName(name, prop)}: ${prop === "text-transform" ? textTransform(val) : css(t, val)};`,
          );
      }
    } else lines.push(`  ${varName(name)}: ${css(tk.type, v)};`);
  };
  for (const set of [sets.brand[brand], sets.theme[mode], sets.typography, sets.components])
    for (const [name, tk] of set) emit(name, tk);
  return `[data-brand="${brand}"][data-theme="${mode}"] {\n${[...new Set(lines)].join("\n")}\n}`;
}

// utility classes per typography style: .ts-body-md-regular { font: … } via component-independent vars
const styles = [...sets.typography].filter(([, tk]) => tk.type === "typography").map(([n]) => n);
const utilities = styles
  .map((n) => {
    const base = varName(n);
    const cls = "ts-" + n.split(".").slice(1).map(kebab).join("-");
    return `.${cls} {\n  font-family: var(${base}-font-family);\n  font-weight: var(${base}-font-weight);\n  font-size: var(${base}-font-size);\n  line-height: var(${base}-line-height);\n  letter-spacing: var(${base}-letter-spacing);\n  text-transform: var(${base}-text-transform);\n}`;
  })
  .join("\n");

const header = "/* GENERATED by scripts/build-css.mjs from tokens/. Do not edit. */\n";
const body = BRANDS.flatMap((b) => MODES.map((m) => block(b, m))).join("\n\n");
mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, `${header}${body}\n\n${utilities}\n`);
console.log(
  `✓ ${OUT} (${BRANDS.length * MODES.length} configurations, ${styles.length} text styles)`,
);
